use cruma_tron_runner::{Endpoint, FileSecretStore, Runner};

let endpoint = Endpoint::from_base_url(&std::env::var("TRON_URL")?)?;
let runner = Runner::builder(endpoint, std::env::var("TRON_WORKER_KEY")?)
    .secret_store(FileSecretStore::new(std::env::var("TRON_SECRET_DIR")?)?)
    .on("send-report", |job| async move {
        // Ok marks the run succeeded and Err marks it failed; both carry a message.
        Ok(format!("sent the report for {}", job.job_name))
    })
    .connect()
    .await?;

// ... keep the process alive; when it is told to shut down:
// finish in-flight work, report it, then close
runner.stop().await;

import { FileSecretStore, ok, Runner } from "@cruma-io/tron-runner";

const runner = new Runner({
  url: process.env.TRON_URL!,
  token: process.env.TRON_WORKER_KEY!,
  secretStore: new FileSecretStore(process.env.TRON_SECRET_DIR!),
});

runner.handle("send-report", (delivery) => {
  // Ok marks the run succeeded and Err marks it failed; both carry a message.
  return ok(`sent the report for ${delivery.jobName}`);
});

await runner.start();
// ... keep the process alive; when it is told to shut down:
await runner.stop(); // finish in-flight work, report it, then close

using Cruma.Tron.Runner;

await using var runner = new RunnerClient(new RunnerClientOptions
{
    TronUrl = new Uri(Environment.GetEnvironmentVariable("TRON_URL")!),
    Token = Environment.GetEnvironmentVariable("TRON_WORKER_KEY")!,
    SecretDirectory = Environment.GetEnvironmentVariable("TRON_SECRET_DIR")!,
});

runner.Handle("send-report", (delivery, cancellationToken) =>
{
    // Ok marks the run succeeded and Err marks it failed; both carry a message.
    return Task.FromResult(Outcome.Ok($"sent the report for {delivery.JobName}"));
});

await runner.ConnectAsync();

// ... keep the process alive; when it is told to shut down:
await runner.StopAsync(); // finish in-flight work, report it, then close

store, err := tronrunner.NewFileSecretStore(os.Getenv("TRON_SECRET_DIR"))
if err != nil {
	return err
}
runner, err := tronrunner.New(tronrunner.Config{
	BaseURL:     os.Getenv("TRON_URL"),
	Token:       os.Getenv("TRON_WORKER_KEY"),
	SecretStore: store,
})
if err != nil {
	return err
}

runner.Handle("send-report", func(ctx context.Context, d tronrunner.Delivery) tronrunner.Outcome {
	// Ok marks the run succeeded and Err marks it failed; both carry a message.
	return tronrunner.Ok("sent the report for " + d.JobName)
})

if err := runner.Connect(ctx); err != nil {
	return err
}

// ... keep the process alive; when it is told to shut down:
return runner.Stop(context.Background()) // finish in-flight work, report it, then close
